// Command gencodes generates the control name tables from the Linux kernel
// header linux/input-event-codes.h.
//
// Run it through go generate in internal/control. The generated file is
// checked in, so building HIDI does not need the header.
package main

import (
	"bufio"
	"bytes"
	"flag"
	"fmt"
	"go/format"
	"log"
	"os"
	"sort"
	"strconv"
	"strings"
)

// rangeMarkers are names the header defines only to mark the start of a
// range of codes. They share their number with the first real code of the
// range, which is the better canonical name; the markers stay accepted as
// aliases.
var rangeMarkers = map[string]bool{
	"BTN_MISC": true, "BTN_MOUSE": true, "BTN_JOYSTICK": true, "BTN_GAMEPAD": true,
	"BTN_DIGI": true, "BTN_WHEEL": true, "BTN_TRIGGER_HAPPY": true,
}

// table collects the names of one event type.
type table struct {
	canonical map[uint16]string // number -> preferred name
	byName    map[string]uint16 // every name, aliases included
}

func newTable() *table {
	return &table{canonical: map[uint16]string{}, byName: map[string]uint16{}}
}

func (t *table) add(name string, num uint16) {
	t.byName[name] = num
	if _, taken := t.canonical[num]; !taken && !rangeMarkers[name] {
		t.canonical[num] = name
	}
}

func main() {
	header := flag.String("header", "/usr/include/linux/input-event-codes.h", "path to input-event-codes.h")
	output := flag.String("output", "codes_gen.go", "file to write")
	flag.Parse()
	log.SetFlags(0)

	f, err := os.Open(*header)
	if err != nil {
		log.Fatal(err)
	}
	defer f.Close()

	// KEY_ and BTN_ names share the number space of EV_KEY events.
	tables := map[string]*table{"KEY": newTable(), "ABS": newTable(), "REL": newTable()}
	tableFor := func(name string) *table {
		prefix, _, _ := strings.Cut(name, "_")
		if prefix == "BTN" {
			prefix = "KEY"
		}
		return tables[prefix]
	}

	sc := bufio.NewScanner(f)
	for sc.Scan() {
		fields := strings.Fields(sc.Text())
		if len(fields) < 3 || fields[0] != "#define" {
			continue
		}
		name, value := fields[1], fields[2]
		t := tableFor(name)
		if t == nil || strings.HasSuffix(name, "_MAX") || strings.HasSuffix(name, "_CNT") {
			continue
		}
		if num, err := strconv.ParseUint(value, 0, 16); err == nil {
			t.add(name, uint16(num))
			continue
		}
		// An alias for a name defined earlier, such as BTN_A for BTN_SOUTH.
		if num, ok := t.byName[value]; ok && tableFor(value) == t {
			t.byName[name] = num
			continue
		}
		log.Fatalf("%s: cannot interpret value %q", name, value)
	}
	if err := sc.Err(); err != nil {
		log.Fatal(err)
	}

	var buf bytes.Buffer
	buf.WriteString("// Code generated by gencodes from linux/input-event-codes.h; DO NOT EDIT.\n\n")
	buf.WriteString("package control\n\n")
	for _, tt := range []struct{ prefix, ident, doc string }{
		{"KEY", "key", "key and button (EV_KEY)"},
		{"ABS", "axis", "absolute axis (EV_ABS)"},
		{"REL", "relative", "relative axis (EV_REL)"},
	} {
		t := tables[tt.prefix]
		fmt.Fprintf(&buf, "// %sNames maps %s codes to their canonical names.\n", tt.ident, tt.doc)
		fmt.Fprintf(&buf, "var %sNames = map[uint16]string{\n", tt.ident)
		nums := make([]int, 0, len(t.canonical))
		for num := range t.canonical {
			nums = append(nums, int(num))
		}
		sort.Ints(nums)
		for _, num := range nums {
			fmt.Fprintf(&buf, "\t0x%03x: %q,\n", num, t.canonical[uint16(num)])
		}
		buf.WriteString("}\n\n")

		fmt.Fprintf(&buf, "// %sCodes maps every %s name, aliases included, to its code.\n", tt.ident, tt.doc)
		fmt.Fprintf(&buf, "var %sCodes = map[string]uint16{\n", tt.ident)
		names := make([]string, 0, len(t.byName))
		for name := range t.byName {
			names = append(names, name)
		}
		sort.Strings(names)
		for _, name := range names {
			fmt.Fprintf(&buf, "\t%q: 0x%03x,\n", name, t.byName[name])
		}
		buf.WriteString("}\n\n")
	}

	src, err := format.Source(buf.Bytes())
	if err != nil {
		log.Fatal(err)
	}
	if err := os.WriteFile(*output, src, 0o644); err != nil {
		log.Fatal(err)
	}
}
